            tagline = "A group of young observers build a shared sky journal and learn how careful records bring people together.",
            parts = listOf(
                StoryPart(1, "A Bright Evening", listOf("On a clear evening, Zainab noticed the Moon above the roofs. It looked different from the shape she had drawn in her notebook the week before.", "She brought the notebook to the after-school science group and asked whether they could track the changes together.", "Their teacher said they could make a calendar using observations from safe, familiar places and reliable astronomy references.")),
                StoryPart(2, "The First Page", listOf("The group chose a simple format: date, approximate time, weather, and a sketch of the Moon's visible shape.", "They agreed not to publish anyone's home address or exact routine. Observations would be shared with first names or initials, and students could contribute from the school courtyard.", "Their teacher explained how cloud cover could make an observation incomplete without making it useless.")),
                StoryPart(3, "Different Views", listOf("Two students made observations on the same evening but drew slightly different shapes. One had watched through thin cloud, while the other had a clear view.", "Instead of deciding that one student was wrong, the group wrote down the conditions beside each drawing.", "They learned that a useful record explains not only what was seen, but also what might have affected the view.")),
                StoryPart(4, "A Library Reference", listOf("The librarian helped the group find a beginner-friendly astronomy book and a printed lunar calendar from a trusted science source.", "The students compared their sketches with the reference and learned that the Moon's changing appearance follows a repeating cycle.", "They added source notes so future readers could distinguish their observations from published information.")),
                StoryPart(5, "The Cloudy Week", listOf("For several evenings, clouds covered the Moon. Some students worried that the calendar would have blank spaces.", "Zainab suggested drawing a cloud symbol and recording that the Moon was not visible. Their teacher agreed that an honest note was better than inventing an observation.", "The blank spaces became part of the record, showing how weather had shaped the group's week.")),
                StoryPart(6, "A Question from a Younger Class", listOf("A younger class asked whether the Moon changed its shape. The science group prepared an explanation using a lamp, a ball, and a darkened classroom.", "They showed how the lit portion visible from Earth changes as the Moon moves around our planet.", "They explained that the Moon itself does not become a different shape, then helped the younger pupils make paper calendars.")),
                StoryPart(7, "The Community Noticeboard", listOf("The group asked permission to display selected sketches on the library noticeboard. They included dates and short captions, but no personal contact details.", "A retired teacher added a note about watching the Moon with her father when she was young. She asked the students to preserve her wording exactly.", "The display began collecting memories as well as scientific observations.")),
                StoryPart(8, "Checking the Dates", listOf("Before printing the calendar, the students checked every date against their original notebooks. They found one entry copied onto the wrong day.", "They corrected it openly, with a small note explaining the change. Their teacher praised them for treating accuracy as more important than looking perfect.", "The final calendar included a short guide to observation and a reminder that clouds and bright city lights can affect what people see.")),
                StoryPart(9, "An Evening for Everyone", listOf("The library hosted a family sky evening in its courtyard. Adults and children used the calendar to identify the Moon's phase and compare it with the group's sketches.", "The event did not use telescopes or require anyone to look toward the Sun. The teacher kept the activity focused on the Moon and visible constellations.", "Visitors contributed questions and suggested future topics, including planets and seasonal stars.")),
                StoryPart(10, "The Next Cycle", listOf("When the Moon's cycle began again, the group opened a fresh page in the notebook. Some original students had moved on, but younger pupils were ready to continue.", "Zainab handed over the observation guide and explained why every entry should include its date and viewing conditions.", "The calendar had become a shared record: part science project, part community memory, and a reminder that the sky offers something new whenever people take time to look carefully."))
